// Title: Check Aspose.Cells HTML export for only standard <!-- --> comments and ensure no downlevel‑revealed <![if ...]> tags using C#
// Common Searches: C# code to verify Aspose.Cells HTML output contains only standard comment tags | how to detect <![if]> conditional comments in HTML generated by Aspose.Cells | regex pattern for finding downlevel‑revealed comment tags in Aspose.Cells HTML export | validate HTML comments after saving a workbook to HTML with Aspose.Cells .NET | prevent conditional comments in Aspose.Cells HTML conversion C#
// Tags: Aspose.Cells HTML comment verification | downlevel revealed comment detection | standard <!-- --> comment enforcement | C# regex for HTML comment validation | conditional comment removal Aspose.Cells

using System;
using System.IO;
using System.Text;
using System.Text.RegularExpressions;
using Aspose.Cells;

// The example creates a workbook, saves it to an in‑memory HTML stream with Aspose.Cells, reads the HTML as UTF‑8 text, and uses a regular expression to detect any downlevel‑revealed comment patterns (<![...]>). It reports success when only standard <!-- --> comments are present and failure when conditional comments are found.
class HtmlCommentVerifier
{
    static void Main()
    {
        // Create a new workbook and add some data (lifecycle rule: create)
        Workbook workbook = new Workbook();
        Worksheet sheet = workbook.Worksheets[0];
        sheet.Cells["A1"].PutValue("Sample Data");

        // Save the workbook to HTML in a memory stream (lifecycle rule: save)
        using (MemoryStream htmlStream = new MemoryStream())
        {
            workbook.Save(htmlStream, SaveFormat.Html);
            htmlStream.Position = 0;

            // Read the HTML content as a string
            string htmlContent = Encoding.UTF8.GetString(htmlStream.ToArray());

            // Verify that the HTML contains only standard comment tags (<!-- comment -->)
            // and does NOT contain downlevel-revealed comments (e.g., <![if ...]>)
            bool hasDownlevelRevealed = Regex.IsMatch(htmlContent, @"<!\[[^\]]+\]>", RegexOptions.IgnoreCase);

            if (hasDownlevelRevealed)
            {
                Console.WriteLine("Verification failed: Downlevel-revealed comment tags were found.");
            }
            else
            {
                Console.WriteLine("Verification succeeded: Only standard comment tags are present.");
            }
        }
    }
}
